package main

// nilIndex marks the absence of a neighbour in the recency list.
const nilIndex = -1

// entry is one cached key/value pair, linked into the recency list by index.
type entry struct {
	key, value string
	prev       int32 // towards most recently used
	next       int32 // towards least recently used
}

// Cache is a fixed-capacity LRU cache. Entries live in a pool slice and are
// linked into a doubly linked recency list by index; a map indexes them by key.
// Every operation runs in O(1) expected time.
type Cache struct {
	capacity int
	entries  []entry
	index    map[string]int32
	head     int32 // most recently used, or nilIndex
	tail     int32 // least recently used, or nilIndex
	free     int32 // head of the free-entry stack (linked via next), or nilIndex
}

// NewCache returns an empty cache holding at most capacity keys (minimum 1).
func NewCache(capacity int) *Cache {
	capacity = max(capacity, 1)
	hint := min(capacity, 1<<20)
	return &Cache{
		capacity: capacity,
		entries:  make([]entry, 0, hint),
		index:    make(map[string]int32, hint),
		head:     nilIndex,
		tail:     nilIndex,
		free:     nilIndex,
	}
}

// Len reports the number of keys held.
func (c *Cache) Len() int { return len(c.index) }

// Set inserts or overwrites key, making it the most recently used. If the
// cache would exceed its capacity, the least recently used key is evicted.
func (c *Cache) Set(key, value string) {
	if i, ok := c.index[key]; ok {
		c.entries[i].value = value
		c.touch(i)
		return
	}
	if len(c.index) == c.capacity {
		c.remove(c.tail)
	}
	i := c.alloc()
	c.entries[i] = entry{key: key, value: value}
	c.index[key] = i
	c.pushFront(i)
}

// Get returns the value for key and whether it was present. A hit makes the
// key the most recently used.
func (c *Cache) Get(key string) (string, bool) {
	i, ok := c.index[key]
	if !ok {
		return "", false
	}
	c.touch(i)
	return c.entries[i].value, true
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key string) bool {
	i, ok := c.index[key]
	if !ok {
		return false
	}
	c.remove(i)
	return true
}

func (c *Cache) alloc() int32 {
	if c.free != nilIndex {
		i := c.free
		c.free = c.entries[i].next
		return i
	}
	c.entries = append(c.entries, entry{})
	return int32(len(c.entries) - 1)
}

// remove unlinks entry i, drops it from the index and recycles its slot.
func (c *Cache) remove(i int32) {
	e := &c.entries[i]
	delete(c.index, e.key)
	c.unlink(i)
	*e = entry{next: c.free} // release the strings
	c.free = i
}

func (c *Cache) touch(i int32) {
	if c.head != i {
		c.unlink(i)
		c.pushFront(i)
	}
}

func (c *Cache) unlink(i int32) {
	e := &c.entries[i]
	if e.prev != nilIndex {
		c.entries[e.prev].next = e.next
	} else {
		c.head = e.next
	}
	if e.next != nilIndex {
		c.entries[e.next].prev = e.prev
	} else {
		c.tail = e.prev
	}
}

func (c *Cache) pushFront(i int32) {
	e := &c.entries[i]
	e.prev = nilIndex
	e.next = c.head
	if c.head != nilIndex {
		c.entries[c.head].prev = i
	} else {
		c.tail = i
	}
	c.head = i
}

// Command lru simulates an LRU cache driven by commands on standard input.
//
// The first line holds the capacity; each later line is one of
// SET <key> <value>, GET <key>, DEL <key> or SIZE.
package main

import (
	"bufio"
	"fmt"
	"io"
	"math"
	"os"
	"strconv"
	"strings"
)

func main() {
	out := bufio.NewWriterSize(os.Stdout, 1<<16)
	if err := run(os.Stdin, out); err != nil {
		fmt.Fprintln(os.Stderr, "lru:", err)
		os.Exit(1)
	}
	if err := out.Flush(); err != nil {
		fmt.Fprintln(os.Stderr, "lru:", err)
		os.Exit(1)
	}
}

// run executes the command stream read from r, writing results to w.
func run(r io.Reader, w *bufio.Writer) error {
	data, err := io.ReadAll(r)
	if err != nil {
		return err
	}
	// Keys and values are substrings of the single input string, so storing
	// them in the cache needs no per-entry allocation.
	input := string(data)

	first, rest, _ := strings.Cut(input, "\n")
	cache := NewCache(parseCapacity(first))

	for len(rest) > 0 {
		var line string
		line, rest, _ = strings.Cut(rest, "\n")
		line = strings.TrimSuffix(line, "\r")

		cmd, line := nextToken(line)
		switch cmd {
		case "SET":
			key, line := nextToken(line)
			value, _ := nextToken(line)
			if key != "" {
				cache.Set(key, value)
			}
		case "GET":
			key, _ := nextToken(line)
			if value, ok := cache.Get(key); ok {
				w.WriteString(value)
			} else {
				w.WriteString("NULL")
			}
			w.WriteByte('\n')
		case "DEL":
			key, _ := nextToken(line)
			if cache.Delete(key) {
				w.WriteString("1\n")
			} else {
				w.WriteString("0\n")
			}
		case "SIZE":
			w.Write(strconv.AppendInt(w.AvailableBuffer(), int64(cache.Len()), 10))
			w.WriteByte('\n')
		}
	}
	return nil
}

// nextToken skips leading spaces and splits off the next space-delimited token.
func nextToken(s string) (token, rest string) {
	s = strings.TrimLeft(s, " ")
	if i := strings.IndexByte(s, ' '); i >= 0 {
		return s[:i], s[i:]
	}
	return s, ""
}

// parseCapacity reads the leading decimal digits of s (after optional blanks),
// saturating at math.MaxUint32 and returning at least 1.
func parseCapacity(s string) int {
	s = strings.TrimLeft(s, " \t")
	var v uint64
	for i := 0; i < len(s) && s[i] >= '0' && s[i] <= '9'; i++ {
		v = min(v*10+uint64(s[i]-'0'), math.MaxUint32)
	}
	return int(max(v, 1))
}
